const express = require('express');
const Stripe = require('stripe');
const db = require('../db');

const app = express();
const stripe = new Stripe(process.env.STRIPE_API_KEY);

app.get('/api/vendors/connect/:stripeAccountId/financials', async (req, res) => {
  const { stripeAccountId } = req.params;

  // Validate that stripeAccountId is mapped to req.user.id
  const vendorRecord = await db('vendor_profiles')
    .where({ user_id: req.user.id, stripe_account_id: stripeAccountId })
    .first();
  if (!vendorRecord) {
    return res.status(403).json({ error: 'Access denied: not authorized for this connected account' });
  }

  try {
    const balance = await stripe.balance.retrieve({
      stripeAccount: stripeAccountId
    });

    return res.json({
      stripeAccountId,
      available: balance.available,
      pending: balance.pending
    });
  } catch (err) {
    return res.status(500).json({ error: 'Could not fetch balance' });
  }
});

module.exports = app;
